const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-path-worker", node: "Code: Scan Single Folder" } });
const fs = require('fs');
const path = require('path');

const SUPPORTED_EXTENSIONS = new Set(['.pdf','.txt','.md','.docx','.doc','.xlsx','.xls','.odt','.ods','.jpg','.jpeg','.png','.webp','.heic','.tif','.tiff']);
const MAX_DEPTH = 10;

function isSymlink(fullPath) {
  try {
    return fs.lstatSync(fullPath).isSymbolicLink();
  } catch(e) {
    return false;
  }
}

function scanDir(dirPath, depth) {
  if (depth > MAX_DEPTH) return [];
  let results = [];
  let entries;
  try {
    entries = fs.readdirSync(dirPath, { withFileTypes: true });
  } catch(e) {
    if (e.code === 'ELOOP') {
      logger.info(`ELOOP skipped (server-side symlink loop): ${dirPath}`);
    }
    return [];
  }
  for (const entry of entries) {
    if (entry.isSymbolicLink()) continue;
    const fullPath = path.join(dirPath, entry.name);
    if (isSymlink(fullPath)) continue;
    if (entry.isDirectory()) {
      results = results.concat(scanDir(fullPath, depth + 1));
    } else if (entry.isFile()) {
      const ext = path.extname(entry.name).toLowerCase();
      if (SUPPORTED_EXTENSIONS.has(ext)) {
        try {
          const stat = fs.statSync(fullPath);
          results.push({ file_path: fullPath, file_type: ext.slice(1), file_size: stat.size });
        } catch(e) {
          logger.info(`stat error on ${fullPath}: ${e.code} ${e.message}`);
        }
      }
    }
  }
  return results;
}

const folderItem = $input.first().json; // { id, path, suggested_type, lock_owner }
const folderPath = folderItem.path;
const suggestedType = folderItem.suggested_type || 'auto';
const errors = [];
let files = [];
try {
  fs.accessSync(folderPath, fs.constants.R_OK);
  files = scanDir(folderPath, 0);
} catch(e) {
  errors.push({ folder: folderPath, error: e.message, code: e.code });
  logger.info(`Folder access error [${e.code}]: ${folderPath} — ${e.message}`);
}

const allFiles = files.map(f => ({ ...f, suggested_type: suggestedType, folder_id: folderItem.id }));

if (allFiles.length === 0) {
  return [{ json: { _no_files: true, scanned_dirs: 1, scanned_files: 0, new_files: 0, skipped_files: 0, errors: errors } }];
}

logger.info(`Path-Worker scan complete for folder ${folderItem.id} (${folderPath}): ${allFiles.length} files, ${errors.length} errors`);
return allFiles.map(f => ({ json: { ...f, _no_files: false } }));

const fs = require('fs');
const crypto = require('crypto');
const redis = require('redis');

const item = $input.first().json;
const filePath = item.file_path;
const trigger = $('Execute Workflow Trigger').first().json;

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
let redisOk = false;
try { await client.connect(); redisOk = true; } catch(ce) {}

try {
  if (redisOk) await client.incr(`alice:dms:scanner:stats:folder:${trigger.id}:scanned_files`).catch(() => {});

  const fileBuffer = fs.readFileSync(filePath);
  const hash = crypto.createHash('sha256').update(fileBuffer).digest('hex');

  return [{
    json: {
      ...item,
      file_hash: 'sha256:' + hash,
      original_size: item.file_size
    }
  }];
} catch(e) {
  if (redisOk) {
    await client.rPush(`alice:dms:scanner:stats:folder:${trigger.id}:errors`, 'hash_error:' + filePath + ':' + e.message).catch(() => {});
    await client.incr(`alice:dms:scanner:stats:folder:${trigger.id}:skipped_files`).catch(() => {});
  }
  return [{
    json: {
      ...item,
      file_hash: null,
      _skip: true,
      _skip_reason: 'hash_error: ' + e.message
    }
  }];
} finally {
  if (redisOk) await client.quit().catch(() => {});
}

const redis = require('redis');
const fs = require('fs');
const item = $input.first().json;
const filePath = item.file_path;
const currentHash = item.file_hash;
const trigger = $('Execute Workflow Trigger').first().json;

if (!currentHash) {
  return [{ json: { ...item, _lifecycle_action: 'skip', _skip: true } }];
}

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
try {
  await client.connect();
} catch(connErr) {
  return [{ json: { ...item, _lifecycle_action: 'skip', _skip: true, _skip_reason: 'redis_connect_error: ' + connErr.message } }];
}
try {
  // Check 1: Known path -> hash mapping
  const knownHashForPath = await client.hGet('alice:dms:path_to_hash', filePath);

  if (knownHashForPath) {
    if (knownHashForPath === currentHash) {
      await client.incr(`alice:dms:scanner:stats:folder:${trigger.id}:skipped_files`);
      return [{ json: { ...item, _lifecycle_action: 'already_processed', _skip: true } }];
    } else {
      // File changed: same path, different hash
      await client.sRem('alice:dms:processed', knownHashForPath);
      return [{ json: { ...item, _lifecycle_action: 'replace', _old_hash: knownHashForPath } }];
    }
  }

  // Check 2: Is this hash already processed (potentially at a different path)?
  const isProcessed = await client.sIsMember('alice:dms:processed', currentHash);

  if (isProcessed) {
    const knownPaths = await client.sMembers('alice:dms:hash_to_paths:' + currentHash);

    if (knownPaths.length === 0) {
      return [{ json: { ...item, _lifecycle_action: 'new' } }];
    }

    const existingPaths = knownPaths.filter(p => {
      try { fs.accessSync(p, fs.constants.F_OK); return true; } catch(e) { return false; }
    });

    if (existingPaths.length === 0) {
      return [{ json: { ...item, _lifecycle_action: 'update_path', _old_paths: knownPaths } }];
    } else {
      const deadPaths = knownPaths.filter(p => !existingPaths.includes(p));
      for (const p of deadPaths) {
        await client.sRem('alice:dms:hash_to_paths:' + currentHash, p);
      }
      return [{ json: { ...item, _lifecycle_action: 'add_path', _known_paths: existingPaths } }];
    }
  }

  // Check 3: Is hash currently in the processing queue?
  const isQueued = await client.sIsMember('alice:dms:queued_files', currentHash);
  if (isQueued) {
    await client.incr(`alice:dms:scanner:stats:folder:${trigger.id}:skipped_files`);
    return [{ json: { ...item, _lifecycle_action: 'already_queued', _skip: true } }];
  }

  return [{ json: { ...item, _lifecycle_action: 'new' } }];

} catch(e) {
  await client.rPush(`alice:dms:scanner:stats:folder:${trigger.id}:errors`, 'lifecycle_error:' + filePath + ':' + e.message).catch(() => {});
  return [{ json: { ...item, _lifecycle_action: 'skip', _skip: true, _skip_reason: 'lifecycle_error: ' + e.message } }];
} finally {
  await client.quit();
}

