const fs = require('fs');
const item = $input.first().json;
let needs_ocr = true;
try {
  // Read first 64KB only — enough to find text markers
  const fd = fs.openSync(item.file_path, 'r');
  const buf = Buffer.alloc(65536);
  fs.readSync(fd, buf, 0, 65536, 0);
  fs.closeSync(fd);
  const sample = buf.toString('latin1');
  // Font is present in every PDF with a real text layer
  needs_ocr = !(sample.includes('Font'));
} catch(e) {
  // On error: safe default — assume OCR needed
  needs_ocr = true;
}
return [{ json: { ...item, needs_ocr } }];

