const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-path-worker", node: "Code: Renew Path Lock" } });
const redis = require('redis');
const trigger = $('Execute Workflow Trigger').first().json;
const lockKey = `alice:dms:scanner:lock:folder:${trigger.id}`;
const owner = trigger.lock_owner;
const LOCK_TTL_MS = 180000;
const RUN_TIME_LIMIT_SECONDS = 7200; // PROJ-94: 2h per-folder run limit

const RENEW_SCRIPT = `
local raw = redis.call('GET', KEYS[1])
if not raw then return 0 end
local ok, data = pcall(cjson.decode, raw)
if not ok or data.owner ~= ARGV[1] then return 0 end
data.last_heartbeat = ARGV[2]
redis.call('SET', KEYS[1], cjson.encode(data), 'PX', ARGV[3])
return 1
`;

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
let renewed = false;
// PROJ-94: fail-open time-limit check; stays false unless run_start proves the limit was exceeded
let timeLimitReached = false;
let elapsedSeconds = 0;
try {
  await client.connect();
  const res = await client.eval(RENEW_SCRIPT, { keys: [lockKey], arguments: [owner, new Date().toISOString(), String(LOCK_TTL_MS)] });
  renewed = (res === 1);
  try {
    const startStr = await client.get(`alice:dms:scanner:stats:folder:${trigger.id}:run_start`);
    const startMs = parseInt(startStr || '0', 10);
    if (startMs > 0) {
      elapsedSeconds = Math.floor((Date.now() - startMs) / 1000);
      timeLimitReached = elapsedSeconds >= RUN_TIME_LIMIT_SECONDS;
    }
  } catch(te) {
    // Fail-open: a Redis hiccup during the time check must not abort a healthy run.
    logger.info(`[Path-Worker] Time-limit check error for folder ${trigger.id}: ${te.message} - continuing run (fail-open)`);
  }
} catch(e) {
  logger.info(`[Path-Worker] Lock renewal error for folder ${trigger.id}: ${e.message} - treating as lock lost`);
  renewed = false;
} finally {
  await client.quit().catch(() => {});
}
return [{ json: { ...$input.first().json, _lock_still_held: renewed, _time_limit_reached: timeLimitReached, _elapsed_seconds: elapsedSeconds } }];

