const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-path-worker", node: "Code: Abort on Time Limit" } });
const redis = require('redis');
const trigger = $('Execute Workflow Trigger').first().json;
const folderId = trigger.id;
const elapsedSeconds = $input.first().json._elapsed_seconds || 0;

// PROJ-94: read progress so far for the abort log; the lock itself is released
// by the existing "Code: Release Path Lock" node downstream of the summary.
let scannedFiles = 0, newFiles = 0, skippedFiles = 0, lifecycleFiles = 0;
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
try {
  await client.connect();
  const [sf, nf, sk, lf] = await Promise.all([
    client.get(`alice:dms:scanner:stats:folder:${folderId}:scanned_files`),
    client.get(`alice:dms:scanner:stats:folder:${folderId}:new_files`),
    client.get(`alice:dms:scanner:stats:folder:${folderId}:skipped_files`),
    client.get(`alice:dms:scanner:stats:folder:${folderId}:lifecycle_files`)
  ]);
  scannedFiles = parseInt(sf || '0', 10);
  newFiles = parseInt(nf || '0', 10);
  skippedFiles = parseInt(sk || '0', 10);
  lifecycleFiles = parseInt(lf || '0', 10);
} catch(e) {
  logger.info(`[Path-Worker] Could not read progress stats on time-limit abort for folder ${folderId}: ${e.message}`);
} finally {
  await client.quit().catch(() => {});
}

logger.info(JSON.stringify({
  event: 'alice-dms-path-worker-time-limit-abort',
  reason: 'time_limit_reached',
  folder_id: folderId,
  path: trigger.path,
  elapsed_seconds: elapsedSeconds,
  scanned_files: scannedFiles,
  new_files: newFiles,
  skipped_files: skippedFiles,
  lifecycle_files: lifecycleFiles,
  timestamp: new Date().toISOString()
}));

// Stop the file loop: no further files are scanned/processed this run. Remaining
// files are picked up by the next hourly dispatcher run (lock is released below).
return [{ json: { _time_limit_reached: true, _elapsed_seconds: elapsedSeconds } }];

const redis = require('redis');
const trigger = $('Execute Workflow Trigger').first().json;
const folderId = trigger.id;
// PROJ-94: set when the run was aborted by the 2h per-folder time limit
const timeLimitReached = ($input.first().json || {})._time_limit_reached === true;
let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });

let scannedFiles = 0, newFiles = 0, skippedFiles = 0, lifecycleFiles = 0, errors = [], startMs = 0;
try {
  await client.connect();
  const [sf, nf, sk, lf, errLen, startStr] = await Promise.all([
    client.get(`alice:dms:scanner:stats:folder:${folderId}:scanned_files`),
    client.get(`alice:dms:scanner:stats:folder:${folderId}:new_files`),
    client.get(`alice:dms:scanner:stats:folder:${folderId}:skipped_files`),
    client.get(`alice:dms:scanner:stats:folder:${folderId}:lifecycle_files`),
    client.lLen(`alice:dms:scanner:stats:folder:${folderId}:errors`),
    client.get(`alice:dms:scanner:stats:folder:${folderId}:run_start`)
  ]);
  scannedFiles = parseInt(sf || '0', 10);
  newFiles = parseInt(nf || '0', 10);
  skippedFiles = parseInt(sk || '0', 10);
  lifecycleFiles = parseInt(lf || '0', 10);
  startMs = parseInt(startStr || '0', 10);
  if (errLen > 0) {
    errors = await client.lRange(`alice:dms:scanner:stats:folder:${folderId}:errors`, 0, -1);
  }
  await client.quit();
} catch(e) {
  try { await client.quit(); } catch(qe) {}
}

return [{ json: {
  _no_files: false,
  _time_limit_reached: timeLimitReached,
  abort_reason: timeLimitReached ? 'time_limit_reached' : null,
  folder_id: folderId,
  path: trigger.path,
  scanned_files: scannedFiles,
  new_files: newFiles,
  skipped_files: skippedFiles,
  lifecycle_files: lifecycleFiles,
  errors: errors,
  runtime_seconds: startMs > 0 ? Math.round((Date.now() - startMs) / 1000) : 0,
  completed_at: new Date().toISOString()
} }];

const winston = require('winston');
const logger = winston.createLogger({ level: 'info', transports: [ new winston.transports.File({ filename: "/home/node/.n8n/logs/n8n.log" }) ], defaultMeta: { workflow: "alice-dms-path-worker", node: "Code: Release Path Lock" } });
const redis = require('redis');
const trigger = $('Execute Workflow Trigger').first().json;
const lockKey = `alice:dms:scanner:lock:folder:${trigger.id}`;
const owner = trigger.lock_owner;

const RELEASE_SCRIPT = `
local raw = redis.call('GET', KEYS[1])
if not raw then return 0 end
local ok, data = pcall(cjson.decode, raw)
if not ok or data.owner ~= ARGV[1] then return 0 end
redis.call('DEL', KEYS[1])
return 1
`;

let redisPw = ''; try { redisPw = $env.REDIS_PASSWORD || ''; } catch(e) {}
const client = redis.createClient({ socket: { host: 'redis', port: 6379 }, password: redisPw || undefined });
let released = false;
try {
  await client.connect();
  const res = await client.eval(RELEASE_SCRIPT, { keys: [lockKey], arguments: [owner] });
  released = (res === 1);
  if (!released) logger.info(`[Path-Worker] Release skipped for folder ${trigger.id}: not owner (already expired/reassigned)`);
} catch(e) {
  logger.info(`[Path-Worker] Release error for folder ${trigger.id}: ${e.message}`);
} finally {
  await client.quit().catch(() => {});
}
return [{ json: { ...$input.first().json, folder_id: trigger.id, path: trigger.path, _lock_released: released } }];
